import{c as i,Q as n,j as e,m as s}from"./chunks/framework.DOi4mjdC.js";const h=JSON.parse('{"title":"调用算子时出现无法打开config.ini的报错","description":"","frontmatter":{},"headers":[{"level":1,"title":"调用算子时出现无法打开config.ini的报错","slug":"调用算子时出现无法打开configini的报错"},{"level":2,"title":"现象描述","slug":"现象描述"},{"level":2,"title":"问题根因","slug":"问题根因"},{"level":2,"title":"处理步骤","slug":"处理步骤"}],"relativePath":"guide/编程指南/附录/FAQ/调用算子时出现无法打开config-ini的报错.md","filePath":"guide/编程指南/附录/FAQ/调用算子时出现无法打开config-ini的报错.md"}'),t={name:"guide/编程指南/附录/FAQ/调用算子时出现无法打开config-ini的报错.md"};function o(p,a,l,c,r,d){return n(),e("div",null,[...a[0]||(a[0]=[s(`<h1 id="调用算子时出现无法打开config-ini的报错" tabindex="-1">调用算子时出现无法打开config.ini的报错 <a class="header-anchor" href="#调用算子时出现无法打开config-ini的报错" aria-label="Permalink to &quot;调用算子时出现无法打开config.ini的报错&quot;">​</a></h1><h2 id="现象描述" tabindex="-1">现象描述 <a class="header-anchor" href="#现象描述" aria-label="Permalink to &quot;现象描述&quot;">​</a></h2><p>自定义算子包安装部署后，在调用已部署的算子时，出现如下json文件获取失败的报错信息：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[INFO] Start get path and read binary_info_config.json.</span></span>
<span class="line"><span>[WARNING] Get jsonfile path for */binary_info_config.json failed, errmsg:No such file or directory.</span></span>
<span class="line"><span>[ERROR] Get path and read binary_info_config.json failed, please check if the opp_kernel package is installed!</span></span></code></pre></div><p>通过查询前文的报错信息，上述json文件获取失败的原因是前置流程中无法打开config.ini，提示信息如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[INFO] Start to get opp kernel base path, default custom opp kernel is in ASCEND_OPP_PATH.</span></span>
<span class="line"><span>[INFO] The real path of config.ini is */opp/vendors/config.ini.</span></span>
<span class="line"><span>[WARNING]  Can not open file: */opp/vendors/config.ini.</span></span></code></pre></div><h2 id="问题根因" tabindex="-1">问题根因 <a class="header-anchor" href="#问题根因" aria-label="Permalink to &quot;问题根因&quot;">​</a></h2><p>根因在于当前调用算子的用户缺少对算子包部署目录下的config.ini（ */opp/vendors/config.ini）文件的读权限。config.ini文件权限默认为640，仅允许部署用户和同属组用户访问，当前执行用户与安装用户非同一属组，缺少读权限，导致算子调用失败。</p><p>比如下述场景即会导致调用算子时出现执行报错：root用户安装部署自定义算子包，HwHiAiUser属组用户调用已部署的自定义算子。</p><h2 id="处理步骤" tabindex="-1">处理步骤 <a class="header-anchor" href="#处理步骤" aria-label="Permalink to &quot;处理步骤&quot;">​</a></h2><p>联系自定义算子包安装用户修改config.ini权限为644：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>chmod 644 config.ini</span></span></code></pre></div>`,12)])])}const f=i(t,[["render",o]]);export{h as __pageData,f as default};
